actions.script:
const edl = ec.entity.makeDataLoader()
let source = ""
if (types || components) {
    if (types) edl.dataTypes(types.split(","))
    if (components) edl.componentNameList(components.split(","))
    source = `Types: ${types || 'N/A'}, Components: ${components || 'N/A'}`
} else if (location) {
    // Java blocks a remote location in production; the loader here reads local and component locations only
    if (/^https?:/i.test(String(location))) {
        ec.message.addError(ec.l10n.localize("Remote data load location is not allowed"))
        return
    }
    edl.location(location)
    source = location
} else if (csvText) {
    edl.csvText(csvText)
    source = ec.l10n.localize("CSV Text Box")
} else if (jsonText) {
    edl.jsonText(jsonText)
    source = ec.l10n.localize("JSON Text Box")
} else if (xmlText) {
    edl.xmlText(xmlText)
    source = ec.l10n.localize("XML Text Box")
} else {
    ec.message.addMessage(ec.l10n.localize("No parameters specified, not loading data"))
    return
}
if (timeout) edl.transactionTimeout(parseInt(timeout, 10))
if (dummyFks) edl.dummyFks(true)
if (useTryInsert) edl.useTryInsert(true)
if (hideNoActionFiles) edl.messageNoActionFiles(false)
// the entities no generic write takes, no account's password and no existing account's identity fields
// from a request (SEC-TLS-81)
edl.restrictSensitiveEntities(true)
edl.protectUserAccounts(true)

// with wrapForeignKeys the load runs on a worker between the jobs of plan#LoadWrap: the foreign keys of the tables
// in the data are dropped, the data loaded, and the keys made again whatever the load did (the DatabaseLoadWrap
// ServiceJob, moqui.tools.DatabaseLoadServices.run#LoadWrap)
if (!checkOnly && String(context.wrapForeignKeys) == 'true') {
    if (!ec.user.hasPermission('DATABASE_ADMIN')) { ec.message.addError(ec.l10n.localize('A load with the foreign keys dropped needs the DATABASE_ADMIN permission')); return }
    // the entities of the data, read and not written; a load by types or components may touch any table. Data
    // that does not read (a value its field's type does not take, a location not there) is a form error, with
    // the input kept and no job started, not a failed request (TOOL-UI-007)
    const notStarted = (reason) => ec.message.addError(ec.resource.expand('Nothing was loaded and no job was started: ${reason}', '', {reason}))
    let entityNames = []
    if (!(types || components)) {
        const names = new Set()
        const failures = []
        let values
        try {
            values = edl.list([], failures)
        } catch (e) {
            notStarted(String(e && e.message || e))
            return
        }
        if (failures.length) { notStarted(failures.map(failure => `[${failure.location}] ${failure.reason}`).join('; ')); return }
        for (const value of values) {
            const name = value && (typeof value.getEntityName === 'function' ? value.getEntityName() : value.entityName)
            if (name) names.add(String(name))
        }
        entityNames = Array.from(names)
        if (!entityNames.length) { ec.message.addError(ec.l10n.localize('The data names no entity to load')); return }
    }
    const wrap = ec.service.sync().name('org.moqui.dev.DatabaseServices.plan#LoadWrap').parameters({db, entityNames,
        description: entityNames.length ? 'Foreign keys around a load of ' + entityNames.length + ' entities' : 'Foreign keys around a load of every entity'}).call() || {}
    if (ec.message.hasError()) return
    for (const warning of wrap.warnings || []) ec.message.addMessage(String(warning), 'warning')
    if (!wrap.dropJobId || !wrap.restoreJobId) { ec.message.addError(String(wrap.jobReason || ec.l10n.localize('The foreign keys could not be planned'))); return }
    const parameters = {dropJobId: wrap.dropJobId, restoreJobId: wrap.restoreJobId, loadKind: 'data',
        onlyCreate: !!onlyCreate, dummyFks: !!dummyFks, useTryInsert: !!useTryInsert}
    for (const name of ['location', 'types', 'components']) if (context[name]) parameters[name] = String(context[name])
    // the text goes in a private file the job reads and deletes, not in the job run's parameters (SEC-DAT-96)
    if (!(types || components || location)) {
        const kind = csvText ? 'csv' : jsonText ? 'json' : xmlText ? 'xml' : null
        if (kind) parameters.textLocation = ec.resource.writePrivateFile(String(context[kind + 'Text']), kind)
    }
    if (timeout) parameters.transactionTimeout = parseInt(timeout, 10)
    let jobRunId
    try {
        jobRunId = ec.service.job('DatabaseLoadWrap').parameters(parameters).run()
    } catch (e) {
        if (parameters.textLocation) ec.resource.getLocationReference(parameters.textLocation).delete()
        throw e
    }
    ec.message.addMessage(`Started the load on a worker (job run ${jobRunId}): database job ${wrap.dropJobId} drops ${(wrap.dropStatements || []).length} foreign keys, then the data is loaded, then database job ${wrap.restoreJobId} makes them again. A notification says how it ended; Database › Jobs shows both jobs.`, 'info')
    return
}

if (checkOnly) {
    // do nothing, checkOnly handled in screen actions before render
} else {
    if (onlyCreate) edl.onlyCreate(true)
    const messages = []
    const failures = []
    // a text that fails loads nothing (it is one transaction) and its error names the record and the
    // database's reason: a form error, with the text kept, not a failed request (TOOL-UI-005)
    let recordsLoaded = 0
    try {
        recordsLoaded = edl.load(messages, failures)
    } catch (e) {
        ec.message.addError(ec.resource.expand('Nothing was loaded from [${source}]: ${reason}', '', {source, reason: String(e && e.message || e)}))
        return
    }
    // a file that failed loaded nothing and the others loaded: each failed one is a form error naming it,
    // beside the count of what did load (TOOL-UI-006)
    for (const failure of failures) ec.message.addError(ec.resource.expand('Could not load [${location}]: ${reason}', '',
        {location: String(failure.location), reason: String(failure.reason)}))
    const recordsText = recordsLoaded == 1 ? '1 record' : `${recordsLoaded} records`
    ec.message.addMessage(ec.resource.expand('Loaded ${recordsText} from [${source}]', '', {recordsText, source}))
    // as JSON: the session keeps text, and an array put there reads back as one string after the redirect
    ec.web.sessionAttributes["DataLoad.messages"] = JSON.stringify(messages.map(String))
}

let fieldsUpdated = 0
const rowOpList = rowOps ? String(rowOps).split(',') : []
for (const rowOp of rowOpList) {
    const rowOpJson = StringUtilities.base64UrlDecode(rowOp)
    let rowOpMap = null
    try { rowOpMap = JSON.parse(rowOpJson) } catch (e) { rowOpMap = null }
    if (!rowOpMap || typeof rowOpMap !== 'object') { ec.message.addMessage(`Row is not readable, not stored: ${rowOpJson}`, 'warning'); continue }
    if (!rowOpMap.pk || typeof rowOpMap.pk !== 'object') { ec.message.addMessage(`No PK in row: ${rowOpJson}`); continue }

    const entityName = String(rowOpMap.entity || '')
    const ed = entityName ? ec.entity.getEntityDefinition(entityName) : null
    if (ed == null) { ec.message.addMessage(`Entity ${entityName} not found for row: ${rowOpJson}`); continue }
    if (WebUtilities.isGenericWriteRefused(entityName)) {
        ec.message.addMessage(`Entity ${entityName} is not available through this tool, row not stored: ${JSON.stringify(rowOpMap.pk)}`, 'warning')
        continue
    }

    let valueMap = null
    if (rowOpMap.field) {
        valueMap = Object.assign({}, rowOpMap.pk, {[rowOpMap.field]: rowOpMap.value})
    } else if (rowOpMap.createValues && typeof rowOpMap.createValues === 'object') {
        valueMap = Object.assign({}, rowOpMap.createValues, rowOpMap.pk)
    } else {
        // TODO: support create (at least for fields with complete PK)
        ec.message.addMessage(`Row has no field or create values, not updating: ${rowOpJson}`)
        continue
    }
    // every field the row sets, its primary key map's included: a password or identity field is not taken
    const secretField = Object.keys(valueMap).find(name => WebUtilities.isGenericWriteRefused(entityName, name))
    if (secretField) {
        ec.message.addMessage(`Field ${secretField} of ${entityName} is not available through this tool, row not stored: ${JSON.stringify(rowOpMap.pk)}`, 'warning')
        continue
    }

    const stored = ec.entity.makeValue(entityName)
    stored.setFields(valueMap, true, null, null)
    if (rowOpMap.field) {
        stored.createOrUpdate()
        fieldsUpdated++
    } else {
        stored.create()
        fieldsUpdated += (Object.keys(valueMap).length - Object.keys(rowOpMap.pk).length)
    }
}

ec.message.addMessage(`Updated ${fieldsUpdated} fields`)

const storedMessages = ec.web.sessionAttributes['DataLoad.messages']
if (storedMessages) {
    ec.web.sessionAttributes.remove('DataLoad.messages')
    try { messages = JSON.parse(String(storedMessages)) } catch (e) { messages = [String(storedMessages)] }
    if (!Array.isArray(messages)) messages = [String(messages)]
}

diffInfoList = []
if (!ec.artifactExecution.isPermitted(sri.getActiveScreenDef().getLocation(), 'AT_XML_SCREEN', 'all')) {
    ec.message.addError(ec.l10n.localize("Checking data needs authorization for all actions on this screen"))
    return
}
const edl = ec.entity.makeDataLoader()
let source = ""
if (types || components) {
    if (types) edl.dataTypes(types.split(","))
    if (components) edl.componentNameList(components.split(","))
    source = `Types: ${types || 'N/A'}, Components: ${components || 'N/A'}`
} else if (location) {
    edl.location(location)
    source = location
} else if (csvText) {
    edl.csvText(csvText)
    source = ec.l10n.localize("CSV Text Box")
} else if (jsonText) {
    edl.jsonText(jsonText)
    source = ec.l10n.localize("JSON Text Box")
} else if (xmlText) {
    edl.xmlText(xmlText)
    source = ec.l10n.localize("XML Text Box")
} else {
    ec.message.addMessage(ec.l10n.localize("No parameters specified, not loading data"))
    return
}
if (hideNoActionFiles) edl.messageNoActionFiles(false)
edl.restrictSensitiveEntities(true)

messageList = []
diffInfoList = []
fieldsChecked = edl.checkInfo(diffInfoList, messages)

CollectionUtilities.orderMapList(diffInfoList, ['entity', 'pk', 'field'])
CollectionUtilities.paginateList("diffInfoList", null, ec.context)
